// "Check signature": accept only calls signed by the site's contact function (api/contact.ts).
//   X-Portfolio-Timestamp: <unix seconds>
//   X-Portfolio-Signature: sha256=<hex HMAC-SHA256(secret, "<timestamp>." + raw body)>
// Same rules as src/lib/signature.ts; tests/unit/n8n-code.test.ts signs with that module and runs this
// script, so both sides must agree. The Webhook node needs the "Raw Body" option: re-serialised JSON
// would never match the signature.
//
// Secret: WEBHOOK_SECRET in n8n's environment (needs N8N_BLOCK_ENV_ACCESS_IN_NODE=false and
// NODE_FUNCTION_ALLOW_BUILTIN=crypto). Output: { ok, status, reason } or { ok: true, payload }.
const SETTINGS = {"workflowName":"Portfolio contact form","webhookPath":"portfolio-contact","timezone":"Europe/Berlin","maxAgeSeconds":600,"dedupeHours":24,"sheetName":"Leads","columns":["Received","Name","Company","E-mail","Message","Came from","Language","Test"],"texts":{"en":{"subject":"Thank you for your message","body":"Hello,\n\nthank you for your message. I have received it and will get back to you as soon as possible.\n\nBest regards\n{owner}\n\nThis is an automatic reply to a message sent through the contact form on my website."},"de":{"subject":"Vielen Dank für Ihre Nachricht","body":"Guten Tag,\n\nvielen Dank für Ihre Nachricht. Ich habe sie erhalten und melde mich so bald wie möglich bei Ihnen.\n\nMit freundlichen Grüßen\n{owner}\n\nDies ist eine automatische Antwort auf eine Nachricht über das Kontaktformular meiner Website."}}};

const crypto = require('crypto');
const reject = (status, reason) => [{ json: { ok: false, status, reason } }];

let secret = '';
try {
  secret = $env.WEBHOOK_SECRET || '';
} catch (e) {
  secret = ''; // env access blocked: same answer as a missing secret
}
if (!secret) return reject(500, 'WEBHOOK_SECRET is not set in n8n');

const headers = $input.first().json.headers || {};
const ts = String(headers['x-portfolio-timestamp'] || '');
const given = String(headers['x-portfolio-signature'] || '');
if (!/^\d{1,12}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > SETTINGS.maxAgeSeconds) {
  return reject(401, 'missing or expired timestamp');
}

let raw;
try {
  raw = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return reject(400, 'no raw body (turn on the Webhook option "Raw Body")');
}
const expected =
  'sha256=' +
  crypto
    .createHmac('sha256', secret)
    .update(ts + '.')
    .update(raw)
    .digest('hex');
const a = Buffer.from(given);
const b = Buffer.from(expected);
// Length check first: timingSafeEqual throws on different lengths.
if (a.length !== b.length || !crypto.timingSafeEqual(a, b)) return reject(401, 'bad signature');

let payload;
try {
  payload = JSON.parse(raw.toString('utf8'));
} catch (e) {
  return reject(400, 'body is not JSON');
}
if (!payload || payload.event !== 'contact' || payload.version !== 1) return reject(400, 'unknown event');
const inquiry = payload.inquiry || {};
for (const field of ['name', 'email', 'message']) {
  if (typeof inquiry[field] !== 'string' || !inquiry[field].trim()) return reject(400, `missing ${field}`);
}

// Idempotency: the site retries when an answer gets lost. The same body (same receivedAt) must not
// create a second row or a second e-mail. Static data persists only for the active (published) workflow.
const key = crypto.createHash('sha256').update(raw).digest('hex');
const state = $getWorkflowStaticData('global');
state.contacts = state.contacts || {};
const now = Date.now();
for (const [k, at] of Object.entries(state.contacts)) {
  if (now - at > SETTINGS.dedupeHours * 3600 * 1000) delete state.contacts[k];
}
if (state.contacts[key]) return [{ json: { ok: false, status: 200, reason: 'already processed' } }];
state.contacts[key] = now;

return [{ json: { ok: true, status: 200, payload } }];

// "Build messages": the lead-list row and the e-mails for one verified inquiry. Plain text only.
//
// Rules:
// - Test events (local runs, preview deployments) go only to CONTACT_TEST_EMAIL, never to real people.
// - The auto-reply contains NO text from the form (not even the name): otherwise anyone could make this
//   mailbox send arbitrary text to any address they type in.
// - Sheet cells that start with = + - @ get a leading ' so Google Sheets doesn't run them as formulas.
// Addresses come from n8n's environment: CONTACT_OWNER_EMAIL, CONTACT_FROM_EMAIL (default: owner),
// CONTACT_OWNER_NAME, CONTACT_TEST_EMAIL.
const SETTINGS = {"workflowName":"Portfolio contact form","webhookPath":"portfolio-contact","timezone":"Europe/Berlin","maxAgeSeconds":600,"dedupeHours":24,"sheetName":"Leads","columns":["Received","Name","Company","E-mail","Message","Came from","Language","Test"],"texts":{"en":{"subject":"Thank you for your message","body":"Hello,\n\nthank you for your message. I have received it and will get back to you as soon as possible.\n\nBest regards\n{owner}\n\nThis is an automatic reply to a message sent through the contact form on my website."},"de":{"subject":"Vielen Dank für Ihre Nachricht","body":"Guten Tag,\n\nvielen Dank für Ihre Nachricht. Ich habe sie erhalten und melde mich so bald wie möglich bei Ihnen.\n\nMit freundlichen Grüßen\n{owner}\n\nDies ist eine automatische Antwort auf eine Nachricht über das Kontaktformular meiner Website."}}};

const env = (name) => {
  try {
    return String($env[name] || '');
  } catch (e) {
    return '';
  }
};

const { payload } = $input.first().json;
const inquiry = payload.inquiry;
const test = payload.test === true;
const lang = SETTINGS.texts[inquiry.locale] ? inquiry.locale : 'en';

const cell = (value) => {
  const s = String(value == null ? '' : value);
  return /^[=+\-@\t\r]/.test(s) ? "'" + s : s;
};
const oneLine = (value, max) =>
  String(value == null ? '' : value)
    .replace(/[\r\n]+/g, ' ')
    .slice(0, max);

const received = new Intl.DateTimeFormat('sv-SE', {
  timeZone: SETTINGS.timezone,
  dateStyle: 'short',
  timeStyle: 'short',
}).format(new Date(payload.receivedAt));

const values = [
  received,
  inquiry.name,
  inquiry.company,
  inquiry.email,
  inquiry.message,
  inquiry.source,
  lang,
  test ? 'yes' : '',
];
const row = {};
SETTINGS.columns.forEach((column, i) => {
  row[column] = cell(values[i]);
});

const owner = env('CONTACT_OWNER_EMAIL');
const from = env('CONTACT_FROM_EMAIL') || owner;
const testTo = env('CONTACT_TEST_EMAIL');
const ownerTo = test ? testTo : owner;
const senderTo = test ? testTo : inquiry.email;
const prefix = test ? '[TEST] ' : '';

const ownerMail = {
  to: ownerTo,
  from,
  replyTo: inquiry.email,
  subject: prefix + oneLine(`New inquiry from ${inquiry.name}${inquiry.company ? ` (${inquiry.company})` : ''}`, 150),
  text: [
    `Name: ${inquiry.name}`,
    `Company: ${inquiry.company || '-'}`,
    `E-mail: ${inquiry.email}`,
    `Came from: ${inquiry.source || '-'}`,
    `Language: ${lang}`,
    `Received: ${received} (${SETTINGS.timezone})`,
    '',
    inquiry.message,
    '',
    'Reply to this e-mail to answer the sender.',
  ].join('\n'),
};

const texts = SETTINGS.texts[lang];
const senderMail = {
  to: senderTo,
  from,
  subject: prefix + texts.subject,
  text: texts.body.replace('{owner}', env('CONTACT_OWNER_NAME')),
};

let skipReason = '';
if (!from || !ownerTo) skipReason = test ? 'test event without CONTACT_TEST_EMAIL' : 'CONTACT_OWNER_EMAIL is not set';

return [
  {
    json: {
      test,
      row,
      ownerMail,
      senderMail,
      sendEmails: skipReason === '',
      skipReason,
      telegramText: oneLine(
        `${prefix}New inquiry: ${inquiry.name}${inquiry.company ? ` (${inquiry.company})` : ''}`,
        200,
      ),
    },
  },
];
